import @vibe/concurrent { TaskGroup, TaskHandle }

fn launch[rg, e](g: TaskGroup[rg, e], f: () -> Int with Exception + e) -> TaskHandle[rg, e, Int] {
  TaskGroup::spawn(g, f)
}

export let main = () -> Int with Exception {
  TaskGroup::run((g) -> { TaskHandle::join(launch(g, () -> { 42 })) })
}

